-- delaware Manufacturing Playbook — Supabase Seed Script
-- Creates 4 tables and inserts all content data (7 storylines × 3 personas = 21 content blocks)
-- Run this in the Supabase SQL Editor to set up the database

-- ═══════════════════════════════════════════════════════
-- 1. DROP EXISTING TABLES (if re-seeding)
-- ═══════════════════════════════════════════════════════
DROP TABLE IF EXISTS storyline_content CASCADE;
DROP TABLE IF EXISTS storylines CASCADE;
DROP TABLE IF EXISTS sub_segments CASCADE;
DROP TABLE IF EXISTS personas CASCADE;

-- ═══════════════════════════════════════════════════════
-- 2. CREATE TABLES
-- ═══════════════════════════════════════════════════════

CREATE TABLE personas (
  id TEXT PRIMARY KEY,
  label TEXT NOT NULL,
  subtitle TEXT NOT NULL,
  emoji TEXT NOT NULL,
  focus TEXT NOT NULL,
  care_most JSONB NOT NULL DEFAULT '[]',
  keeps_up_at_night JSONB NOT NULL DEFAULT '[]'
);

CREATE TABLE sub_segments (
  id TEXT PRIMARY KEY,
  label TEXT NOT NULL,
  short TEXT NOT NULL,
  description TEXT NOT NULL
);

CREATE TABLE storylines (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  icon TEXT NOT NULL,
  accent TEXT NOT NULL,
  relevant_segments JSONB NOT NULL DEFAULT '[]',
  sort_order INT NOT NULL DEFAULT 0
);

CREATE TABLE storyline_content (
  id SERIAL PRIMARY KEY,
  storyline_id TEXT NOT NULL REFERENCES storylines(id),
  persona_id TEXT NOT NULL REFERENCES personas(id),
  pain_point JSONB NOT NULL,
  strategic_talking_points JSONB NOT NULL DEFAULT '[]',
  tactical_solutions JSONB NOT NULL DEFAULT '[]',
  market_insights JSONB NOT NULL DEFAULT '[]',
  reference_customers JSONB NOT NULL DEFAULT '[]',
  conversation_starters JSONB NOT NULL DEFAULT '[]',
  UNIQUE(storyline_id, persona_id)
);

-- ═══════════════════════════════════════════════════════
-- 3. DISABLE RLS (internal tool, no auth for V1)
-- ═══════════════════════════════════════════════════════
ALTER TABLE personas ENABLE ROW LEVEL SECURITY;
ALTER TABLE sub_segments ENABLE ROW LEVEL SECURITY;
ALTER TABLE storylines ENABLE ROW LEVEL SECURITY;
ALTER TABLE storyline_content ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Allow public read on personas" ON personas FOR SELECT USING (true);
CREATE POLICY "Allow public read on sub_segments" ON sub_segments FOR SELECT USING (true);
CREATE POLICY "Allow public read on storylines" ON storylines FOR SELECT USING (true);
CREATE POLICY "Allow public read on storyline_content" ON storyline_content FOR SELECT USING (true);

-- ═══════════════════════════════════════════════════════
-- 4. INSERT PERSONAS
-- ═══════════════════════════════════════════════════════

